// Minimal stand-in for the `@rbxts/react` types that `componentProp` reads.
declare namespace React {
	interface ReactElement<P = any> {
		props: P;
	}

	type ReactNode = boolean | null | number | ReactElement | string | undefined;

	interface FunctionComponent<P = {}> {
		(props: P): ReactNode;
	}

	type FC<P = {}> = FunctionComponent<P>;

	interface ComponentClass<P = {}> {
		new (props: P): { render(): ReactNode };
	}

	type ComponentType<P = {}> = ComponentClass<P> | FunctionComponent<P>;

	function memo<P extends object>(component: FunctionComponent<P>): FunctionComponent<P>;

	function createElement(type: unknown, props?: unknown): ReactElement;
}

export = React;
